diff --git a/broker/change/link_test.go b/broker/change/link_test.go
new file mode 100644
index 000000000..34ffa05f7
--- /dev/null
+++ b/broker/change/link_test.go
@@ -0,0 +1,106 @@
+package change
+
+import (
+	"strings"
+	"testing"
+)
+
+// REQ: LOOP-10, CHG-2, A11
+
+// linkEnv has an open finding F1 with its regression and one held-back
+// case linked to it by someone other than Loop 2 (the A11 harness).
+func linkEnv(t *testing.T) *env {
+	t.Helper()
+	// The tree holds one governance file, so a delete of it is an edit.
+	e := newEnv(t, func(c *Config) { c.Initial["suites/readme"] = []byte("cases live in the pipeline") })
+	e.cases(12, ClassSkill, "skills/greet", "hello")
+	for _, c := range []Case{
+		{ID: "loop2/F1", Class: ClassSkill, Input: []byte("skills/fix"), Expect: []byte("yes"), Finding: "F1"},
+		{ID: "held/F1/v1", Class: ClassSkill, Input: []byte("skills/fix2"), Expect: []byte("yes"), Finding: "F1"},
+	} {
+		if err := e.p.AddSecurityCase(c); err != nil {
+			t.Fatal(err)
+		}
+	}
+	return e
+}
+
+// P3-4b item 4: a fix for F qualifies only if every case linked to F
+// passes, the held-back one included (6(g)).
+func TestAFixMustPassEveryCaseLinkedToItsFinding(t *testing.T) {
+	e := linkEnv(t)
+	r := e.propose(Candidate{Source: Local, Finding: "F1", Files: Tree{"skills/greet": []byte("hello"), "skills/fix": []byte("yes")}})
+	if r.State != StateRejected || r.Reason != ReasonLinked {
+		t.Fatalf("passes the visible regression only: %+v", r)
+	}
+	r = e.propose(Candidate{Source: Local, Finding: "F1", Files: Tree{"skills/greet": []byte("hello"), "skills/fix": []byte("yes"), "skills/fix2": []byte("yes")}})
+	if r.State != StateAdopted || r.Linked != 2 || r.LinkedPassed != 2 {
+		t.Fatalf("passes every linked case: %+v", r)
+	}
+}
+
+// Other candidates, and fixes for other findings, keep PS1 for the cases
+// linked to F1: they must not regress, and need not pass. F2 has its own
+// linked case, which the fix passes; with none it fails closed (below).
+func TestCasesLinkedToAnotherFindingKeepPS1(t *testing.T) {
+	for _, finding := range []string{"", "F2"} {
+		e := linkEnv(t)
+		if err := e.p.AddSecurityCase(Case{ID: "loop2/F2", Class: ClassSkill, Input: []byte("skills/greet"), Expect: []byte("hello"), Finding: "F2"}); err != nil {
+			t.Fatal(err)
+		}
+		r := e.propose(Candidate{Source: Local, Finding: finding, Files: Tree{"skills/greet": []byte("hello")}})
+		if r.State != StateAdopted {
+			t.Fatalf("finding %q: %+v", finding, r)
+		}
+	}
+}
+
+// A case linked to F that the evaluator cannot run on the fix counts as a
+// fail, whatever the candidate's class: a fix cannot qualify by being
+// untestable (6(f)).
+func TestAnUnevaluatedLinkedCaseFailsTheFix(t *testing.T) {
+	e := linkEnv(t)
+	e.ev.decline = func(t Tree, _ Probe) bool { _, ok := t["config/x"]; return ok }
+	r := e.propose(Candidate{Source: Local, Finding: "F1", Files: Tree{"config/x": []byte("1"), "skills/fix": []byte("yes"), "skills/fix2": []byte("yes")}})
+	if r.State != StateRejected || r.Reason != ReasonLinked {
+		t.Fatalf("%+v", r)
+	}
+}
+
+// CHG-2: a candidate cannot add, remove or relink a case linked to its
+// own finding. Cases are not tree files; every path that names the suite
+// is rejected before evaluation, and the suite keeps its cases.
+func TestACandidateCannotTouchItsFindingsCases(t *testing.T) {
+	e := linkEnv(t)
+	before := e.p.SecurityCount()
+	for _, c := range []Candidate{
+		{Source: Local, Finding: "F1", Files: Tree{"suites/held/F1/v1": []byte(`{"finding":"F2"}`)}},
+		{Source: Local, Finding: "F1", Files: Tree{"suites/new": []byte(`{"finding":"F1"}`)}},
+		{Source: Local, Finding: "F1", Files: Tree{"security/loop2/F1": []byte("x")}},
+	} {
+		if r := e.propose(c); r.State != StateRejected || !strings.Contains(r.Reason, "owner-approved intent") {
+			t.Fatalf("%+v: %+v", c.Files, r)
+		}
+	}
+	if n := e.p.SecurityCount(); n != before {
+		t.Fatalf("security cases %d, were %d", n, before)
+	}
+	// The link is kept as added.
+	for _, c := range e.p.st.Cases {
+		if strings.HasSuffix(c.ID, "F1") || strings.HasPrefix(c.ID, "held/F1") {
+			if c.Finding != "F1" {
+				t.Fatalf("%s linked to %q", c.ID, c.Finding)
+			}
+		}
+	}
+}
+
+// L3 on #464: a fix for a finding no case is linked to cannot pass every
+// linked case vacuously; it is rejected, whatever else it passes.
+func TestAFixForAFindingWithNoLinkedCaseIsRejected(t *testing.T) {
+	e := linkEnv(t)
+	r := e.propose(Candidate{Source: Local, Finding: "F9", Files: Tree{"skills/greet": []byte("hello")}})
+	if r.State != StateRejected || r.Reason != ReasonUnlinked || r.Linked != 0 {
+		t.Fatalf("%+v", r)
+	}
+}
diff --git a/broker/change/loop10_test.go b/broker/change/loop10_test.go
new file mode 100644
index 000000000..057284a34
--- /dev/null
+++ b/broker/change/loop10_test.go
@@ -0,0 +1,102 @@
+package change
+
+import (
+	"testing"
+)
+
+// REQ: LOOP-10, CHG-2
+
+// P3-4b item 6: a fix candidate for an open finding fails qualification,
+// each way with its own reason, and the security suite never shrinks.
+func TestEachWeakeningFixFailsWithItsOwnReason(t *testing.T) {
+	fixed := Tree{"skills/greet": []byte("hello"), "skills/fix": []byte("yes"), "skills/fix2": []byte("yes")}
+	with := func(extra Tree) Tree {
+		out := Tree{}
+		for k, v := range fixed {
+			out[k] = v
+		}
+		for k, v := range extra {
+			out[k] = v
+		}
+		return out
+	}
+	cases := []struct {
+		name string
+		c    Candidate
+		why  string
+	}{
+		{"(a) edits the regression", Candidate{Files: with(Tree{"suites/loop2/F1": []byte(`{"expect":"fail"}`)})},
+			"changes suites, which only an owner-approved intent changes (CHG-2)"},
+		{"(b) deletes it", Candidate{Files: fixed, Delete: []string{"suites/readme"}},
+			"deletes from suites, which only an owner-approved intent changes (CHG-2)"},
+		{"(c) skips it through graders", Candidate{Files: with(Tree{"graders/security": []byte(`"pass"`)})},
+			"changes graders, which only an owner-approved intent changes (CHG-2)"},
+		{"(c) skips it through config", Candidate{Files: with(Tree{"config/loop2.json": []byte(`{"fixtures_live":false}`)})},
+			`sets "fixtures_live" in config/loop2.json, which turns fixture grading off or down; no candidate may (LOOP-10)`},
+		{"(c) turns loop 2 off", Candidate{Files: with(Tree{"config/loops.json": []byte(`{"secure":false}`)})},
+			`sets "secure" in config/loops.json, which turns loop 2 off or down; no candidate may (LOOP-10)`},
+		{"(d) widens authority", Candidate{Files: with(Tree{"grants/p4": []byte(`{"verbs":["send"]}`)})},
+			"changes grants, which no candidate may change (LOOP-10)"},
+		{"(e) disables a check", Candidate{Files: with(Tree{"checks/hash": []byte(`"off"`)})},
+			"changes checks, which no candidate may change (LOOP-10)"},
+		{"(e) disables a check through config", Candidate{Files: with(Tree{"config/loop2.json": []byte(`{"checks":{"seeded":false}}`)})},
+			`sets "checks" in config/loop2.json, which disables a loop 2 check; no candidate may (LOOP-10)`},
+		{"(f) leaves the suite unevaluable", Candidate{Files: with(Tree{"config/x": []byte("1")})},
+			"fails the security suite"},
+		{"(g) fails a held-back case", Candidate{Files: Tree{"skills/greet": []byte("hello"), "skills/fix": []byte("yes")}},
+			ReasonLinked},
+	}
+	seen := map[string]string{}
+	for _, tc := range cases {
+		e := linkEnv(t)
+		// The evaluator cannot run the plain security probe on a tree
+		// with config/x: coverage the fix would lose (6(f)).
+		e.ev.decline = func(t Tree, pr Probe) bool {
+			_, ok := t["config/x"]
+			return ok && string(pr.Input) == exfilProbe
+		}
+		before := e.p.SecurityCount()
+		tc.c.Source, tc.c.Finding = Local, "F1"
+		r := e.propose(tc.c)
+		if r.State != StateRejected || r.Reason != tc.why {
+			t.Errorf("%s: %s %q", tc.name, r.State, r.Reason)
+		}
+		if n := e.p.SecurityCount(); n != before {
+			t.Errorf("%s: security cases %d, were %d", tc.name, n, before)
+		}
+		if prev, dup := seen[r.Reason]; dup && tc.name[:3] != prev[:3] {
+			t.Errorf("%s and %s share a reason", prev, tc.name)
+		}
+		seen[r.Reason] = tc.name
+	}
+	// The good fix qualifies.
+	e := linkEnv(t)
+	if r := e.propose(Candidate{Source: Local, Finding: "F1", Files: fixed}); r.State != StateAdopted {
+		t.Fatalf("good fix: %+v", r)
+	}
+}
+
+// Config keys outside the closed list stay ordinary config, and a
+// loop-governing file left as it was is no change to it.
+func TestOnlyListedConfigKeysGovernLoops(t *testing.T) {
+	e := newEnv(t, func(c *Config) {
+		c.Initial["config/loop2.json"] = []byte(`{"checks":{"seeded":true},"note":"a"}`)
+	})
+	e.cases(12, ClassSkill, "skills/greet", "hello")
+	e.owner.approve = true // config is a behavior change the owner approves (CHG-3)
+	r := e.propose(Candidate{Source: Local, Files: Tree{"skills/greet": []byte("hello"), "config/loop2.json": []byte(`{"note":"b","checks":{"seeded":true}}`)}})
+	if r.State == StateRejected {
+		t.Fatalf("unlisted key: %+v", r)
+	}
+	for _, after := range [][]byte{[]byte(`not json`), nil} {
+		c := Candidate{Source: Local, Files: Tree{"skills/greet": []byte("hello")}}
+		if after == nil {
+			c.Delete = []string{"config/loop2.json"}
+		} else {
+			c.Files["config/loop2.json"] = after
+		}
+		if r := e.propose(c); r.State != StateRejected || r.Reason != "changes config/loop2.json, which governs the loops; no candidate may (LOOP-10)" {
+			t.Fatalf("%q: %+v", after, r)
+		}
+	}
+}
