+	f = seedFinding()
+	f.Subject, f.Contain = "other-route", nil
+	r.report(t, f)
+	if len(r.texts) != 1 || !r.urgent[0] || r.texts[0] != "Security checks: Security test other-route fails on my current setup." {
+		t.Fatalf("texts %q urgent %v", r.texts, r.urgent)
