+	if len(r.c.got) != 0 || len(r.g.Evidence()) != 0 || r.p.SecurityCount() != count || len(r.texts) != 0 {
+		t.Fatalf("acted on a refused finding: %d pauses, %d records, %d texts", len(r.c.got), len(r.g.Evidence()), len(r.texts))
+	}
+}
